using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Exploration of numbers, structures, and abstract reasoning." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Understanding the fundamental laws governing the natural world." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and critical analysis of texts." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Examination of past events, civilizations, and their lasting impact." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "The science of life and living organisms." },
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor of Computer Science", Bio = "Dr. Lovelace specializes in algorithm design and computational theory. She has published over 50 papers and holds two patents in parallel computing.", Email = "alovelace@university.edu" },
            new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor of Computer Science", Bio = "Dr. Turing's research focuses on artificial intelligence and machine learning. He leads the university's AI research lab.", Email = "aturing@university.edu" },
            new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor of Mathematics", Bio = "Dr. Noether is a renowned algebraist whose work bridges abstract mathematics and theoretical physics.", Email = "enoether@university.edu" },
            new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Professor of Physics", Bio = "Dr. Feynman is an award-winning physicist known for his engaging lectures and pioneering work in quantum electrodynamics.", Email = "rfeynman@university.edu" },
            new() { Id = 5, Name = "Dr. Maya Angelou", Title = "Professor of English", Bio = "Dr. Angelou is a celebrated author and poet who brings decades of literary experience to the classroom.", Email = "mangelou@university.edu" },
            new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor of History", Bio = "Dr. Zinn is a historian and social commentator specializing in American labor and civil rights history.", Email = "hzinn@university.edu" },
            new() { Id = 7, Name = "Dr. Rosalind Franklin", Title = "Professor of Biology", Bio = "Dr. Franklin's research in molecular biology and X-ray crystallography has contributed to groundbreaking discoveries.", Email = "rfranklin@university.edu" },
            new() { Id = 8, Name = "Dr. Carl Gauss", Title = "Professor of Mathematics", Bio = "Dr. Gauss is an expert in number theory and statistics with 30 years of teaching experience.", Email = "cgauss@university.edu" },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm analysis. Includes hands-on projects in Java.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Room = "Tech Hall 305", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search, knowledge representation, machine learning, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Room = "Tech Hall 110", DepartmentId = 1, InstructorId = 2, IsFeatured = true },
            new() { Id = 4, Code = "CS 350", Title = "Software Engineering", Description = "Principles of software development lifecycle, agile methodologies, version control, testing, and team-based project work.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Room = "Tech Hall 201", DepartmentId = 1, InstructorId = 2 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Science Bldg 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true },
            new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Science Bldg 203", DepartmentId = 2, InstructorId = 3 },
            new() { Id = 7, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Science Bldg 105", DepartmentId = 2, InstructorId = 8 },

            // Physics
            new() { Id = 8, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", Room = "Physics Lab 100", DepartmentId = 3, InstructorId = 4 },
            new() { Id = 9, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, circuits, and Maxwell's equations. Prerequisite: PHYS 101.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Fri Lab 1:00–3:00 PM", Room = "Physics Lab 200", DepartmentId = 3, InstructorId = 4, IsFeatured = true },

            // English
            new() { Id = 10, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Humanities 301", DepartmentId = 4, InstructorId = 5 },
            new() { Id = 11, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Room = "Humanities 205", DepartmentId = 4, InstructorId = 5 },

            // History
            new() { Id = 12, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultural exchanges, and pivotal events from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Humanities 102", DepartmentId = 5, InstructorId = 6 },
            new() { Id = 13, Code = "HIST 202", Title = "Modern American History", Description = "Examination of the United States from the Civil War to the present, including industrialization, civil rights, and globalization.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Room = "Humanities 102", DepartmentId = 5, InstructorId = 6 },

            // Biology
            new() { Id = 14, Code = "BIO 101", Title = "Introduction to Biology", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed 10:00–11:20 AM + Fri Lab 1:00–3:00 PM", Room = "Life Sciences 100", DepartmentId = 6, InstructorId = 7 },
            new() { Id = 15, Code = "BIO 210", Title = "Molecular Biology", Description = "DNA replication, transcription, translation, and gene regulation. Prerequisite: BIO 101.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Life Sciences 210", DepartmentId = 6, InstructorId = 7, IsFeatured = true },
        };
    }

    public List<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public string GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name ?? "Unknown";
}

