@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or keyword…" />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Catalog.GetAllDepartments())
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Search</button>
    </div>
</form>

@{
    var courses = Catalog.SearchCourses(Search, DepartmentId);
}

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
else
{
    <p class="text-muted">Showing @courses.Count course(s)</p>

    <table class="table table-striped table-hover">
        <thead class="table-dark">
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td><strong>@course.Code</strong></td>
                    <td>@course.Title</td>
                    <td>@Catalog.GetDepartmentName(course.DepartmentId)</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

@{
    var course = Catalog.GetCourse(Id);
}

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="courses" class="btn btn-secondary">Back to Courses</a>
}
else
{
    var dept = Catalog.GetDepartment(course.DepartmentId);
    var instructor = Catalog.GetInstructor(course.InstructorId);

    <PageTitle>@course.Code — @course.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            @if (dept is not null)
            {
                <li class="breadcrumb-item"><a href="courses?departmentId=@dept.Id">@dept.Name</a></li>
            }
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <h1>@course.Code — @course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@course.Description</p>

            <h4 class="mt-4">Schedule & Location</h4>
            <table class="table table-bordered w-auto">
                <tr><th>Schedule</th><td>@course.Schedule</td></tr>
                <tr><th>Room</th><td>@course.Room</td></tr>
                <tr><th>Credits</th><td>@course.Credits</td></tr>
                <tr><th>Department</th><td>@(dept?.Name ?? "N/A")</td></tr>
            </table>

            <a href="enroll?courseId=@course.Id" class="btn btn-success mt-2">Enroll in This Course</a>
        </div>

        <div class="col-md-4">
            @if (instructor is not null)
            {
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">Instructor</h5>
                        <h6>@instructor.Name</h6>
                        <p class="text-muted mb-2">@instructor.Title</p>
                        <p>@instructor.Bio</p>
                        <p><strong>Contact:</strong> <a href="mailto:@instructor.Email">@instructor.Email</a></p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course. You will receive a confirmation by email.</p>

<div class="row">
    <div class="col-md-8">
        <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="fullName" class="form-label">Full Name</label>
                <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                <ValidationMessage For="() => Model.FullName" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g. STU12345" />
                <ValidationMessage For="() => Model.StudentId" />
            </div>

            <div class="mb-3">
                <label for="email" class="form-label">Email</label>
                <InputText id="email" @bind-Value="Model.Email" class="form-control" type="email" />
                <ValidationMessage For="() => Model.Email" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in Catalog.GetAllCourses())
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.CourseId" />
            </div>

            <div class="mb-3">
                <label for="comments" class="form-label">Comments (optional)</label>
                <InputTextArea id="comments" @bind-Value="Model.Comments" class="form-control" rows="3" />
                <ValidationMessage For="() => Model.Comments" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        // In production this would persist to a database and send a confirmation email.
        Navigation.NavigateTo($"/enroll/confirmation?courseName={Uri.EscapeDataString(Catalog.GetCourse(Model.CourseId)?.Title ?? "Unknown")}&studentName={Uri.EscapeDataString(Model.FullName)}");
    }

    [Inject] private NavigationManager Navigation { get; set; } = default!;
}

@page "/enroll/confirmation"

<PageTitle>Enrollment Submitted</PageTitle>

<div class="text-center mt-5">
    <h1 class="text-success">✅ Enrollment Request Submitted</h1>
    <p class="lead mt-3">
        Thank you, <strong>@StudentName</strong>! Your enrollment request for
        <strong>@CourseName</strong> has been received.
    </p>
    <p>You will receive a confirmation email within 1–2 business days.</p>
    <div class="mt-4">
        <a href="courses" class="btn btn-outline-primary me-2">Browse More Courses</a>
        <a href="enroll" class="btn btn-outline-secondary">Submit Another Request</a>
    </div>
</div>

@code {
    [SupplyParameterFromQuery] public string? CourseName { get; set; }
    [SupplyParameterFromQuery] public string? StudentName { get; set; }
}

