@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest? Model { get; set; }

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    [Inject] private NavigationManager Navigation { get; set; } = default!;

    protected override void OnInitialized()
    {
        Model ??= new();
        if (CourseId.HasValue && CourseId.Value > 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model!.CourseId);
        var courseName = Uri.EscapeDataString(course?.Title ?? "Unknown");
        var studentName = Uri.EscapeDataString(Model.FullName);
        Navigation.NavigateTo($"/enroll/confirmation?courseName={courseName}&studentName={studentName}");
    }
}

